/** A fixed page linked from About. The web page never chooses the address. */
export type AboutLink = "website" | "source" | "problem" | "licences";

export type Accent = "system" | "ibis";

/**
 * Why a choice for an app was not saved, so the picker can say which part
 * was kept without reading the words.
 */
export type AppChoiceError = {
	code: "not_saved";
	message: string;
} | {
	code: "delivery_not_saved";
};

/** A deliberate delivery choice for one captured app, independent of its format. */
export type AppPaste = "paste" | "copy-only";

/** Settings owns these choices until the picker consumes the same event fields. */
export type Appearance = "system" | "light" | "dark";

/** Why a backup or restore did not happen; the Settings window words it. */
export type BackupProblem = "not-downloaded" | "unreadable" | "not-a-backup" | "settings-file" | "newer" | "invalid" | "not-saved" | "settings-unusable" | "changed";

/** How a check ended. Whoever asked says so in its own place. */
export type CheckResult = "failed" | "newest" | "offered" | "not_run";

export type CitationSpan = {
	item: number | null;
	runs?: DisplayRun[] | null;
	text: string;
};

/**
 * A failed command as the interface receives it: the interface decides
 * from `code`, never from the text in `message`.
 */
export type CommandError = {
	code: "snapshot_changed";
} | {
	code: "library_loading";
} | {
	code: "cancelled";
} | {
	code: "shared_citation_key";
	key: string;
} | {
	code: "failed";
	message: string;
};

export type Copied = {
	/** Unique clipboard-write identity for receipts, even without a native paste proof. */
	delivery?: number | null;
	summary?: ReceiptSummary | null;
	text: string;
	/** What the chosen syntax could not express, and other problems the user should see. */
	warnings: string[];
};

export type DelightFact = "touch" | "scarlet" | "mummies" | "national" | "flight";

export type DelightStatus = "paste-tip" | "library100" | "library1000" | "library10000";

export type DelightView = {
	anniversary: boolean;
	build: string;
	fact: DelightFact | null;
	fun: boolean;
	peck: boolean;
	revision: number;
	status: DelightStatus | null;
};

/** What happened to a copied citation, for the notice to word. */
export type Delivered = {
	/** The app's own name; `None` when it has none. */
	app: string | null;
	outcome: "pasted";
} | {
	outcome: "copied";
	/**
	 * Why Ibis did not paste: a `CopyReason` code such as `terminal`, or
	 * `key-release-failed`. Every copy says why (docs/design/delivery.md).
	 */
	reason: string;
};

/** How much each result row shows (ADR 0020). */
export type Density = "compact" | "comfortable";

export type DesktopShortcut = {
	configurable: boolean;
	guidance: string;
};

/**
 * Output-only passive presentation. The smaller request TextRun contract stays
 * independent of the additional styles a citation processor may produce.
 */
export type DisplayRun = {
	bold: boolean;
	italic: boolean;
	script: Script;
	small_caps?: boolean;
	text: string;
	underline?: boolean;
};

/**
 * A waiting editor, for the picker to name. Each request has its own number,
 * so two in the same format are still two.
 */
export type EditorWaiting = {
	format: string;
	request: number;
};

/** Why the endpoint could not listen. */
export type EndpointProblem = "not-saved" | "port-in-use" | "bad-setting";

/**
 * What Settings shows. The address holds the token: anyone who has it can open
 * the picker, so it stays on this computer and in this window.
 */
export type EndpointStatus = {
	on: boolean;
	problem: EndpointProblem | null;
	url: string | null;
};

/** How an entry copy ended; a refusal says how to get the entry another way. */
export type EntryCopy = "copied" | "no-original" | "repeated" | "dependency" | "changed";

export type FilePreview = {
	content_hash: string;
	html: string | null;
	/**
	 * What the engine says about this citation that is no warning, such as a
	 * full first note; the web view words each from the catalogue.
	 */
	notices?: Notice[];
	problem?: string | null;
	/**
	 * Why this key citation is refused: a key in the project bibliography
	 * names a different work.
	 */
	project_refusal?: string | null;
	spans: CitationSpan[];
	text: string;
	ticket: string;
	warnings: string[];
};

export type FileSelection = {
	cite: string;
	form?: ReferenceForm | null;
	id: ItemRef;
	/** A canonical locator captured from search; its value is never parsed again. */
	locator?: Locator | null;
	/** Raw Page editor text, mutually exclusive with a captured locator. */
	page_input?: string | null;
};

export type FormOption = {
	example: string | null;
	form: ReferenceForm;
	reason: string | null;
};

/** The format a citation for one app uses, and why. */
export type FormatChoice = {
	from: FormatFrom;
	/** Its id in the engine's `outputs` list, when it is listed there. */
	id?: string | null;
	kind: FormatKind;
	/** The output written. */
	output: OutputSpec;
	writing?: WritingName | null;
};

/** Which level chose a citation's format (decision 0042); the engine decides. */
export type FormatFrom = "writing" | "app" | "yours" | "suggestion";

/** The kinds of app a format is chosen for. People never see the word. */
export type FormatKind = "documents" | "keys";

/** A `.bib` file found on this computer. */
export type FoundFile = {
	/** The name of the folder holding it, without the rest of its path. */
	folder: string;
	/** The file name, such as `refs.bib`. */
	name: string;
};

/**
 * Identity inside one library; citation keys are intentionally separate.
 * Non-item kinds use source-namespaced keys (for example `tag:...`) so
 * source tags and collections cannot collide with native item keys.
 */
export type ItemRef = {
	key: string;
	library: LibraryId;
};

export type KeySyntax = "pandoc" | "biblatex" | "natbib" | "latex" | "context" | "typst" | "org-cite" | "myst" | "multi-markdown" | "ascii-doc" | "jupyter" | "jekyll-scholar" | "scannable-cite" | "keys" | "csl-json" | "cayw-json";

/**
 * A library's opaque token. It says nothing about the library: its kind and
 * capabilities are fields of its description, and nothing may read them from
 * here. Sources mint one with [`LibraryId::digest`] over a private key and the
 * source's identity, so a seen id confirms no guessed location.
 */
export type LibraryId = string;

/** A library failure grouped by what the person can do about it. */
export type LibraryProblem = "other" | "missing" | "unreadable" | "zotero_closed" | "zotero_access_off" | "zotero_profiles" | "zotero_missing";

export type LibraryState = "none" | "loading" | "loaded" | "reloading" | "error";

/** Sent to the interface with the `library:changed` event. */
export type LibraryStatus = {
	/**
	 * When the library was last read or found unchanged, in the same unit;
	 * when `stale`, the time of the copy still being searched.
	 */
	checked_at: number | null;
	error: string | null;
	/** A successfully opened snapshot, including a valid empty library. */
	has_snapshot: boolean;
	/** A searched source cannot be watched, so edits show only after a reload. */
	live_updates_off: boolean;
	/** Requested file name only, including during opening and after failure. */
	name: string | null;
	/** Something to tell the user that is not a failure to open. */
	note: string | null;
	/** What kind of failure `error` is, so the picker can offer the fix. */
	problem: LibraryProblem | null;
	/**
	 * What reading found, at most the engine's detail limit, so the footer
	 * can say which entries were skipped and where to look.
	 */
	reading: ReadingNotice[];
	references: number;
	revision: string;
	/** The searchable snapshot contains only bundled invented references. */
	sample?: boolean;
	/** Startup settings recovery, separate from transient library status. */
	settings_notice: string | null;
	/** File name of the searchable snapshot; may differ from the attempted file. */
	snapshot_name: string | null;
	/**
	 * Whether the searchable references are Zotero's, which can differ from
	 * `zotero` (the requested source) after a failed switch.
	 */
	snapshot_zotero: boolean;
	/** Counts in the searchable snapshot by exact source ID; includes empty loaded Zotero libraries. */
	source_counts: { [key: string]: number };
	source_generation: string;
	/** Whether no switch was requested, or its exact native source is the searchable source. */
	source_is_requested: boolean;
	/**
	 * An update of the searched library failed and its earlier references
	 * are still searched; not set when a switch to another library failed.
	 */
	stale: boolean;
	state: LibraryState;
	/**
	 * When a reread of the same library last changed its references during
	 * this run, in milliseconds since 1970 (UTC); `null` if it has not.
	 */
	updated_at: number | null;
	warnings: number;
	/** Whether the requested library is Zotero rather than a file. */
	zotero: boolean;
	/** The Zotero libraries requested, in order; empty for a file. */
	zotero_libraries: ZoteroLibrary[];
};

/** Local calendar facts from the webview clock; eligibility is decided here. */
export type LocalMoment = {
	day: number;
	month: number;
	year: number;
};

/** Picker wire names over the engine's canonical locator vocabulary. */
export type Locator = {
	label: LocatorTerm;
	/** Canonical value, including literal text preserved by the engine. */
	value: string;
};

/** The engine's interpretation, shown so the person can search as typed. */
export type LocatorQuery = {
	locator: Locator;
	/** What remains to search for. */
	search: string;
	/** The text read as the locator, exactly as typed. */
	typed: string;
};

/**
 * CSL 1.0.2 input locator vocabulary, including the disambiguating `-locator` names.
 * https://github.com/citation-style-language/schema/blob/v1.0.2/schemas/input/csl-citation.json
 */
export type LocatorTerm = "act" | "appendix" | "article-locator" | "book" | "canon" | "chapter" | "column" | "elocation" | "equation" | "figure" | "folio" | "issue" | "line" | "note" | "opus" | "page" | "paragraph" | "part" | "rule" | "scene" | "section" | "sub-verbo" | "supplement" | "table" | "timestamp" | "title-locator" | "verse" | "version" | "volume";

/** Whether Ibis starts when the person logs in, as the system reports it. */
export type LoginItem = {
	enabled: boolean;
	/** The app's name, such as "Ibis" or "Ibis Nightly", for the interface. */
	name: string;
	problem: LoginItemProblem | null;
};

/** Why the choice is not what the person asked for. */
export type LoginItemProblem = "unsupported" | "needs_approval" | "refused" | "unreadable";

/** Which part of a record matched a query term. */
export type MatchField = "citekey" | "title" | "author" | "year" | "doi" | "keyword" | "container" | "abstract" | "identifier";

/** Something the person should know before restoring. */
export type Note = "library-not-found" | "shortcut-kept" | "repairs-settings";

export type Notice = "needs-document-context" | "reference-entry" | "full-first-note" | "year-suffix-withheld" | "input-language-unsupported";

/**
 * What the notice says: whether the citation was pasted or only copied, and
 * one line of it.
 */
export type NoticeMessage = {
	/** Ibis's own Light or Dark, set as the notice is shown; absent for System. */
	appearance?: Appearance;
	delivered: Delivered;
	milestone?: number | null;
	more?: number | null;
	/**
	 * The first paste into this word processor: insert with its plugin if the
	 * document uses one.
	 */
	plugin_note?: boolean;
	text: string;
};

/** An app ID that cannot tell Ibis which output its document needs. */
export type OutputQuestion = "browser" | "editor";

export type OutputSpec = {
	/** A command name for syntaxes that support it; engines validate its grammar. */
	command: string | null;
	kind: "key";
	syntax: KeySyntax;
} | {
	kind: "csl";
	style: string;
} | {
	kind: "preset";
	name: string;
};

/** Where Settings opens. */
export type Page = "general" | "look" | "libraries" | "advanced" | "shortcuts" | "citations" | "about" | "paste";

/** Whether Ibis may paste, and where the person turns that on. */
export type PastePermission = {
	granted: boolean;
	/** The list in System Settings that holds the switch, in the system's words. */
	list: string;
	/** This system asks the person before an app may paste for them. */
	needed: boolean;
	/** Ibis pastes on this system; where it only copies, Settings offers no pasting choices. */
	pastes: boolean;
};

/** Missing explicit citation keys in a recognized pasted list. */
export type PastedList = {
	missing: string[];
};

/** Command identifiers shared with KEY_TABLE and the refusal's translated name. */
export type PickerCommand = "format" | "pin" | "keys" | "more" | "change-last" | "source" | "settings" | "quit";

/** What the picker needs to know about the app it was opened from. */
export type PickerDestination = {
	/** The app's own name; `None` when no app was captured. */
	app: string | null;
	/** The captured OS app identifier, used to refuse a save after the target changes. */
	app_id: string | null;
	/** Opaque app-location fingerprint; no path crosses IPC. */
	app_identity: string | null;
	/** The app suggestion, an engine output id; `None` follows the saved default. */
	automatic: string | null;
	/** A proven ordinary target can accept an explicit delivery choice, including recovery. */
	can_choose_paste: boolean;
	/** The current paste policy permits an attempt; final delivery checks still apply. */
	can_paste: boolean;
	context_version?: [number, number] | null;
	/**
	 * The engine's answer: the format the next citation uses and which level
	 * chose it (decision 0042). The picker shows it as it is.
	 */
	format: FormatChoice;
	/** The app cannot identify document syntax; ask until an output is remembered. */
	output_question: OutputQuestion | null;
	/** The separate delivery choice; never inferred from a remembered format. */
	paste: AppPaste | null;
	/** An unrecognised app has a proven target but no delivery choice yet. */
	paste_question: boolean;
	/** The output the person chose to always use for this app. */
	remembered: string | null;
	/** This app needs a delivery choice after an unreadable per-app file; formats use defaults. */
	unreadable: boolean;
	writing_context?: string | null;
	writing_project?: WritingProjectView | null;
};

/**
 * How the picker looks and what it formats with, remembered across restarts
 * (ADR 0020).
 */
export type PickerPreferences = {
	accent?: Accent | null;
	appearance?: Appearance | null;
	density: Density;
	larger_text: boolean;
	/** The menu bar item; on by default. */
	menu_bar: boolean;
	/**
	 * The default output: an id from the engine's list; an id it does not
	 * list was read as the engine's default.
	 */
	output: string;
	/** Enter pastes into the app the picker was opened from; on by default. */
	paste: boolean;
	/** Recent citations per app; on by default. Off records nothing. */
	recent_citations?: boolean | null;
	small_surprises?: boolean | null;
};

/** Only fields deliberately changed in one window cross the write boundary. */
export type PickerPreferencesPatch = {
	accent?: Accent | null;
	appearance?: Appearance | null;
	density?: Density | null;
	larger_text?: boolean | null;
	menu_bar?: boolean | null;
	/** Only an id the engine lists; any other refuses the whole change. */
	output?: string | null;
	paste?: boolean | null;
	recent_citations?: boolean | null;
	small_surprises?: boolean | null;
};

/** The authoritative state after one locked patch and flush. */
export type PickerSave = {
	preferences: PickerPreferences;
};

/** The saved snapshot and the identity of the write that published it. */
export type PreferenceChange = {
	accent?: Accent | null;
	appearance?: Appearance | null;
	density: Density;
	/**
	 * The fields this save set, so a window can tell a choice from an
	 * unchanged value in the snapshot.
	 */
	fields: string[];
	larger_text: boolean;
	/** The menu bar item; on by default. */
	menu_bar: boolean;
	/**
	 * The default output: an id from the engine's list; an id it does not
	 * list was read as the engine's default.
	 */
	output: string;
	/** Enter pastes into the app the picker was opened from; on by default. */
	paste: boolean;
	/** Recent citations per app; on by default. Off records nothing. */
	recent_citations?: boolean | null;
	revision: number;
	small_surprises?: boolean | null;
};

export type PreviewIntent = {
	cancel: boolean;
	context?: [number, number] | null;
	page: number;
	request: number;
};

/** The state of one emitted key in the project bibliography, for the row. */
export type ProjectKeyState = "in" | "missing" | "could-not-check" | "repeated" | "may-name-another";

export type ProjectMark = {
	generation: number;
	/** Where to look in the file, when the state asks a person to look. */
	lines: number[];
	state: ProjectKeyState;
};

export type ProjectState = "reading" | "ready" | "damaged" | "failed";

/** What the picker may show. A file name, never a folder. */
export type ProjectStatus = {
	/** The first lines that could not be read. */
	damaged_lines: number[];
	generation: number;
	name: string;
	/** Why the newest read failed, as a sentence ending in a full stop. */
	reason: string | null;
	/**
	 * Counts reads that changed an answer, which can happen with the status
	 * otherwise the same, as when an entry is added to a healthy file.
	 */
	revision: number;
	state: ProjectState;
};

/** One thing reading the library found: an entry skipped or one to check. */
export type ReadingNotice = {
	/** The engine's warning code, such as `duplicate-key` or `syntax`. */
	code: string;
	/** The repeated key, for `duplicate-key` only: the person's own data. */
	key: string | null;
	line: number | null;
	/** Why, in the engine's words, naming the field to fix when known. */
	why?: string | null;
};

export type ReceiptSummary = {
	more: number;
	text: string;
};

export type RecentGroup = "cited" | "added";

export type RecentIdentity = unknown;

export type ReferenceDetails = {
	current_form: ReferenceForm | null;
	forms: FormOption[];
};

export type ReferenceForm = "normal" | "narrative" | "year-only";

/**
 * One setting a restore changes. Values are as the settings file writes
 * them, as text; `None` is the default. A bibliography is its file name only.
 */
export type RestoreChange = {
	from: string | null;
	setting: string;
	to: string | null;
};

/** What restoring the chosen backup would change, before anything does. */
export type RestorePreview = {
	changes: RestoreChange[];
	made_by: string;
	made_on: System;
	notes: Note[];
	/** Names this preview; only the latest one can be restored. */
	ticket: number;
};

export type RowAction = "copy" | "toggle";

export type Script = "normal" | "subscript" | "superscript";

/** Query text and the explicit choice to read a trailing locator. */
export type SearchQuery = {
	interpret_locators: boolean;
	text: string;
};

/** A search keeps its snapshot identity even when no references match. */
export type SearchReply = {
	interpretation?: LocatorQuery | null;
	list?: PastedList | null;
	results: SearchResult[];
	revision: string;
	/** Nothing matched and the search has filters: the search without them. */
	unfiltered?: string | null;
};

export type SearchResult = {
	/**
	 * How many creators the record names (an organization counts as one),
	 * so a row can name two authors and shorten three or more.
	 */
	author_count: number;
	authors: string;
	cite: string;
	/**
	 * Journal, book or proceedings title, else the publisher; capped at
	 * 120 characters.
	 */
	container: string | null;
	/**
	 * Family name of the first author (or the whole name of an
	 * organization); empty when the record names no authors.
	 */
	first_author: string;
	/** Identity of the record; selection and copying use this, not the key. */
	id: ItemRef;
	/** CSL item type, such as `article-journal`. */
	item_type: string;
	key: string;
	matched: MatchField[];
	/** Only some query words matched; shown under "Closest matches". */
	partial: boolean;
	/** This row's key against the project bibliography of that generation. */
	project?: ProjectMark | null;
	recent?: RecentGroup | null;
	/** Revision captured with the index used for this result. */
	revision: string;
	/** This row comes from the bundled invented library, including while a replacement search is pending. */
	sample?: boolean;
	source: string;
	title: string;
	/**
	 * A word matched only with one spelling change, as the engine decided.
	 * Sent only when true.
	 */
	typo?: boolean;
	/** The year, or the source's own date text: `RecordSummary::year`. */
	year: string | null;
};

/**
 * A formatted bibliography, shown before it is copied. The picker's own
 * citation receipt is untouched.
 */
export type SessionBibliography = {
	content_hash: string;
	html: string | null;
	/**
	 * References this style cannot write, by key or title. They are named so
	 * that the rest can still be used.
	 */
	left_out: string[];
	text: string;
	warnings: string[];
};

export type SessionEdit = {
	id: RecentIdentity;
	kind: "remove";
} | {
	kind: "reset";
} | {
	kind: "undo";
};

export type SessionReferencesView = {
	/**
	 * Listed references from a library that is not open, left out of the
	 * bibliography until it is.
	 */
	absent: number;
	/** The list reached its limit, so a later citation was left off. */
	overflowed: boolean;
	revision: number;
	/** The listed references that are in the open library. */
	rows: SearchResult[];
	undo: UndoView | null;
};

/** Why a shortcut change failed. Only NotSaved changes the working shortcut. */
export type ShortcutRefusal = "invalid" | "needs-modifier" | "app-shortcut" | {
	"picker-shortcut": PickerCommand;
} | "alt-gr" | "in-use" | "unavailable" | "not-saved";

/** Whether the global shortcut is working, shown in the interface. */
export type ShortcutStatus = {
	/** Present on Wayland, including when the portal is unavailable. */
	desktop?: DesktopShortcut | null;
	error: string | null;
	registered: boolean;
	shortcut: string;
};

export type SourceKind = "zotero" | "file";

export type SourcePresentation = {
	icon: SystemIcon | null;
	kind: SourceKind;
	name: string;
	/** The searched library may differ from the selected/default source. */
	status_icon: SystemIcon | null;
};

/** What first-run setup can offer. */
export type Sources = {
	/**
	 * Some folders were too large to search fully, or more files were
	 * found than are listed.
	 */
	cut_short: boolean;
	files: FoundFile[];
	/** The number to send back with a choice from `files`. */
	list: number;
	zotero: ZoteroPresence;
};

/** The operating system an app ID belongs to. */
export type System = "macos" | "windows" | "linux";

export type SystemIcon = {
	bytes: number[];
	mime: string;
};

/** The edit Undo would reverse, for its label. Only the removed row is named. */
export type UndoView = {
	kind: "removed";
	reference: SearchResult | null;
} | {
	kind: "reset";
};

/** Settings › Look's window size. Any other dragged size is Custom. */
export type WindowSize = "small" | "medium" | "large" | "custom";

/** The writing that chose a format. */
export type WritingName = {
	id: string;
	name: string;
};

export type WritingProjectEdit = {
	kind: "create";
	name: string;
	output: string;
} | {
	id: string;
	kind: "rename";
	name: string;
} | {
	id: string;
	kind: "remove";
} | {
	id?: string | null;
	kind: "select";
} | {
	id: string;
	kind: "output";
	output: string;
};

export type WritingProjectView = {
	bibliography: string | null;
	id: string;
	name: string;
	/** A CLI project can name outputs not yet available in the picker. */
	output: string | null;
};

export type WritingProjectsView = {
	active?: WritingProjectView | null;
	/** Owns one picker opening and captured destination; never a path or title. */
	context: string;
	projects: WritingProjectView[];
	selected: string | null;
	session_only: boolean;
};

/** A Zotero group library the user can choose. */
export type ZoteroGroup = {
	id: number;
	name: string;
};

/** Which Zotero library to read. */
export type ZoteroLibrary = "user" | {
	group: number;
};

export type ZoteroPresence = "available" | "access_off" | "absent" | "closed";

/** The Zotero profiles on this computer and the one chosen, by name. */
export type ZoteroProfiles = {
	chosen: string | null;
	names: string[];
	/**
	 * Zotero is running, so it answers for the profile it opened and a choice
	 * here would change nothing on screen.
	 */
	running: boolean;
};
